// A live scene and every live scene under it: what a delete trashes, and where a move may not go.
// UNION, not UNION ALL, so a cycle (the API never makes one) still ends.
func (q *Queries) SceneSubtree(ctx context.Context, arg SceneSubtreeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, sceneSubtree, arg.CampaignID, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

