const tryJobLock = `-- name: TryJobLock :one
SELECT pg_try_advisory_xact_lock($1::bigint) AS locked
`

// Whether this transaction got the job's lock (released when it ends): every pod runs the daily jobs,
// and one does the work.
func (q *Queries) TryJobLock(ctx context.Context, key int64) (bool, error) {
	row := q.db.QueryRow(ctx, tryJobLock, key)
	var locked bool
	err := row.Scan(&locked)
	return locked, err
}

